struct DirectInputElementKey {
  std::string semantic_name;
  uint32_t semantic_index = 0;
  uint32_t location = 0;
  plume::RenderFormat format = plume::RenderFormat::UNKNOWN;
  uint32_t slot_index = 0;
  uint32_t aligned_byte_offset = 0;

  bool operator==(const DirectInputElementKey& other) const {
    return semantic_name == other.semantic_name &&
           semantic_index == other.semantic_index &&
           location == other.location && format == other.format &&
           slot_index == other.slot_index &&
           aligned_byte_offset == other.aligned_byte_offset;
  }
};

struct DirectInputSlotKey {
  uint32_t index = 0;
  uint32_t stride = 0;
  plume::RenderInputSlotClassification classification =
      plume::RenderInputSlotClassification::UNKNOWN;

  bool operator==(const DirectInputSlotKey& other) const {
    return index == other.index && stride == other.stride &&
           classification == other.classification;
  }
};

struct DirectPipelineKey {
  uint64_t vertex_shader_hash = 0;
  uint64_t pixel_shader_hash = 0;
  plume::RenderPrimitiveTopology topology =
      plume::RenderPrimitiveTopology::UNKNOWN;
  uint32_t color_count = 0;
  std::array<plume::RenderFormat, kMaxFableRenderTargets> color_formats = {};
  plume::RenderFormat depth_format = plume::RenderFormat::UNKNOWN;
  bool pm4_valid = false;
  uint32_t depth_control = 0;
  uint32_t stencil_ref_mask = 0;
  uint32_t stencil_ref_mask_bf = 0;
  std::array<bool, kMaxFableRenderTargets> blend_enabled = {};
  std::array<uint32_t, kMaxFableRenderTargets> blend_controls = {};
  std::array<uint32_t, kMaxFableRenderTargets> color_write_masks = {};
  uint32_t cull_control = 0;
  bool force_no_cull = false;
  std::vector<DirectInputSlotKey> input_slots;
  std::vector<DirectInputElementKey> input_elements;

  bool operator==(const DirectPipelineKey& other) const {
    return vertex_shader_hash == other.vertex_shader_hash &&
           pixel_shader_hash == other.pixel_shader_hash &&
           topology == other.topology && color_count == other.color_count &&
           color_formats == other.color_formats &&
           depth_format == other.depth_format &&
           pm4_valid == other.pm4_valid &&
           depth_control == other.depth_control &&
           stencil_ref_mask == other.stencil_ref_mask &&
           stencil_ref_mask_bf == other.stencil_ref_mask_bf &&
           blend_enabled == other.blend_enabled &&
           blend_controls == other.blend_controls &&
           color_write_masks == other.color_write_masks &&
           cull_control == other.cull_control &&
           force_no_cull == other.force_no_cull &&
           input_slots == other.input_slots &&
           input_elements == other.input_elements;
  }
};

void HashCombine(size_t& seed, size_t value) {
  seed ^= value + 0x9E3779B97F4A7C15ull + (seed << 6u) + (seed >> 2u);
}

struct DirectPipelineKeyHash {
  size_t operator()(const DirectPipelineKey& key) const {
    size_t seed = 0;
    HashCombine(seed, std::hash<uint64_t>{}(key.vertex_shader_hash));
    HashCombine(seed, std::hash<uint64_t>{}(key.pixel_shader_hash));
    HashCombine(seed, std::hash<uint32_t>{}(
                          static_cast<uint32_t>(key.topology)));
    HashCombine(seed, std::hash<uint32_t>{}(key.color_count));
    for (plume::RenderFormat format : key.color_formats) {
      HashCombine(seed,
                  std::hash<uint32_t>{}(static_cast<uint32_t>(format)));
    }
    HashCombine(seed, std::hash<uint32_t>{}(
                          static_cast<uint32_t>(key.depth_format)));
    HashCombine(seed, std::hash<bool>{}(key.pm4_valid));
    HashCombine(seed, std::hash<uint32_t>{}(key.depth_control));
    HashCombine(seed, std::hash<uint32_t>{}(key.stencil_ref_mask));
    HashCombine(seed, std::hash<uint32_t>{}(key.stencil_ref_mask_bf));
    for (bool blend_enabled : key.blend_enabled) {
      HashCombine(seed, std::hash<bool>{}(blend_enabled));
    }
    for (uint32_t blend_control : key.blend_controls) {
      HashCombine(seed, std::hash<uint32_t>{}(blend_control));
    }
    for (uint32_t color_write_mask : key.color_write_masks) {
      HashCombine(seed, std::hash<uint32_t>{}(color_write_mask));
    }
    HashCombine(seed, std::hash<uint32_t>{}(key.cull_control));
    HashCombine(seed, std::hash<bool>{}(key.force_no_cull));
    for (const DirectInputSlotKey& slot : key.input_slots) {
      HashCombine(seed, std::hash<uint32_t>{}(slot.index));
      HashCombine(seed, std::hash<uint32_t>{}(slot.stride));
      HashCombine(seed, std::hash<uint32_t>{}(
                            static_cast<uint32_t>(slot.classification)));
    }
    for (const DirectInputElementKey& element : key.input_elements) {
      HashCombine(seed, std::hash<std::string>{}(element.semantic_name));
      HashCombine(seed, std::hash<uint32_t>{}(element.semantic_index));
      HashCombine(seed, std::hash<uint32_t>{}(element.location));
      HashCombine(seed, std::hash<uint32_t>{}(
                            static_cast<uint32_t>(element.format)));
      HashCombine(seed, std::hash<uint32_t>{}(element.slot_index));
      HashCombine(seed, std::hash<uint32_t>{}(element.aligned_byte_offset));
    }
    return seed;
  }
};

struct DirectUploadBufferKey {
  uint64_t hash = 0;
  uint32_t size = 0;
  uint32_t flags = 0;

  bool operator==(const DirectUploadBufferKey& other) const {
    return hash == other.hash && size == other.size && flags == other.flags;
  }
};

struct DirectUploadBufferKeyHash {
  size_t operator()(const DirectUploadBufferKey& key) const {
    size_t seed = 0;
    HashCombine(seed, std::hash<uint64_t>{}(key.hash));
    HashCombine(seed, std::hash<uint32_t>{}(key.size));
    HashCombine(seed, std::hash<uint32_t>{}(key.flags));
    return seed;
  }
};

