  g_direct_renderer.logged_title_scene_clears = 0;
  g_direct_renderer.logged_title_scene_guiquad_promotions = 0;
  g_direct_renderer.logged_title_texture_sync_breakdowns = 0;
  g_direct_renderer.logged_exact_current_producer_owner_cache_hits = 0;
  g_direct_renderer.logged_source5_video_pending_quarantines = 0;
  g_direct_renderer.logged_non_video_pending_quarantines = 0;
