bool DirectResourceHasMeaningfulTextureUpload(
    const PlumeTrackedResource& resource) {
  return resource.texture_upload_has_source && resource.upload_generation != 0 &&
         resource.texture_upload_size != 0;
}

bool DirectResourceHasExactTitleUploadIdentity(
    const PlumeTrackedResource& resource) {
  if (!IsImageResource(resource.kind) || !PlumeGuestImageReady(resource)) {
    return false;
  }

  const uint32_t base = PlumeGuestTextureBaseAddress(resource);
  const uint32_t width = PlumeGuestTextureWidth(resource);
  const uint32_t height = PlumeGuestTextureHeight(resource);
  const FableTextureIdentity* identity =
      FableDirectFindTextureIdentityByObject(resource.guest_address);
  return IsFableTitleUploadedTextureIdentityBase(base, width, height) ||
         IsFableTitleUploadedTextureIdentity(identity) ||
         IsFableTitleGuiTextAtlasObjectAddress(resource.guest_address) ||
         IsFableTitleGuiTextAtlasObjectAddress(resource.parent_address) ||
         IsFableTitleGuiTextAtlasObjectAddress(base);
}

bool DirectExactTitleUploadedResourceHasAuthoredPayload(
    const PlumeTrackedResource& resource) {
  return DirectResourceHasExactTitleUploadIdentity(resource) &&
         DirectResourceHasMeaningfulTextureUpload(resource) &&
         !DirectResourceIsBlankUploadedSampleProxy(resource);
}

bool DirectResourceHasGpuProducedContent(const PlumeTrackedResource& resource) {
  if (!IsImageResource(resource.kind) || !PlumeGuestImageReady(resource)) {
    return false;
  }
  if (DirectResourceHasMeaningfulTextureUpload(resource)) {
    return true;
  }
  return resource.draw_content_serial != 0 || resource.clear_content_serial != 0;
}

bool DirectResourceHasNonBlankUploadOrGpuProducedContent(
    const PlumeTrackedResource& resource) {
  if (!IsImageResource(resource.kind) || !PlumeGuestImageReady(resource)) {
    return false;
  }
  if (DirectResourceHasMeaningfulTextureUpload(resource) &&
      !DirectResourceIsBlankUploadedSampleProxy(resource)) {
    return true;
  }
  return resource.draw_content_serial != 0 || resource.clear_content_serial != 0;
}

bool DirectFableTitleBillboardAtlasHasAuthoritativeUpload(
    const PlumeTrackedResource& resource) {
  return IsFableTitleBillboardAtlasResource(resource) &&
         DirectResourceHasMeaningfulTextureUpload(resource) &&
         resource.texture_upload_hash != 0;
}

bool DirectFableTitleIndirectionHasAuthoritativeUpload(
    const PlumeTrackedResource& resource) {
  if (!IsImageResource(resource.kind) || !PlumeGuestImageReady(resource) ||
      resource.texture_render_target || resource.texture_depth_target ||
      !DirectResourceHasMeaningfulTextureUpload(resource) ||
      resource.texture_upload_hash == 0) {
    return false;
  }
  const uint32_t base = PlumeGuestTextureBaseAddress(resource);
  return IsFableTitleIndirectionTextureBase(base) ||
         IsFableTitleBillboardTileUploadBaseAddress(base);
}

bool DirectResourceHasSampleableContent(const PlumeTrackedResource& resource) {
  if (!IsImageResource(resource.kind) || !PlumeGuestImageReady(resource)) {
    return false;
  }
  if (DirectResourceHasMeaningfulTextureUpload(resource)) {
    return true;
  }
  return resource.draw_content_serial != 0;
}

bool DirectResourceIsPersistentPrivateSampleBacking(
    const PlumeTrackedResource& resource) {
  return DirectResourceHasMeaningfulTextureUpload(resource) ||
         DirectResourceIsPrivateFeedbackAlias(resource) ||
         (resource.plume_owned && !resource.texture_render_target &&
          !resource.texture_depth_target &&
          DirectResourceHasSampleableContent(resource));
}

bool DirectTitleGuiAtlasResourceHasUpload(const PlumeTrackedResource& resource) {
  if (!IsImageResource(resource.kind) || !PlumeGuestImageReady(resource) ||
      resource.texture_render_target || resource.texture_depth_target ||
      !DirectResourceHasMeaningfulTextureUpload(resource) ||
      resource.texture_upload_hash == 0) {
    return false;
  }

  const uint32_t exact_upload_size = ExactFableTitleGuiTextAtlasUploadSize(
      PlumeGuestTextureBaseAddress(resource), PlumeGuestTextureWidth(resource),
      PlumeGuestTextureHeight(resource), PlumeGuestTextureGuestFormat(resource));
  return exact_upload_size != 0 &&
         resource.texture_upload_size == exact_upload_size &&
         (IsFableTitleGuiTextAtlasObjectAddress(resource.guest_address) ||
          IsFableTitleGuiTextAtlasObjectAddress(resource.parent_address) ||
          IsFableTitleGuiTextAtlasObjectAddress(
              PlumeGuestTextureBaseAddress(resource)));
}

bool DirectResourceIsUnbackedSampleProxy(
    const PlumeTrackedResource& resource) {
  return IsImageResource(resource.kind) && PlumeGuestImageReady(resource) &&
         !resource.texture_render_target && !resource.texture_depth_target &&
         !resource.texture_upload_has_source && resource.texture_upload_size == 0 &&
         resource.draw_content_serial == 0 && resource.clear_content_serial == 0;
}

bool DirectResourceIsBlankUploadedSampleProxy(
    const PlumeTrackedResource& resource) {
  return IsImageResource(resource.kind) && PlumeGuestImageReady(resource) &&
         !resource.texture_render_target && !resource.texture_depth_target &&
         DirectResourceHasMeaningfulTextureUpload(resource) &&
         resource.debug_first_nonzero_offset == UINT32_MAX;
}

bool DirectResourceIsFableTinyTitleNeutralTextureLocked(
    uint32_t guest, const PlumeTrackedResource& resource) {
  if (!IsImageResource(resource.kind) || !PlumeGuestImageReady(resource) ||
      resource.texture_render_target || resource.texture_depth_target) {
    return false;
  }

  const uint32_t base = PlumeGuestTextureBaseAddress(resource);
  const uint32_t width = PlumeGuestTextureWidth(resource);
  const uint32_t height = PlumeGuestTextureHeight(resource);
  const FableTextureIdentity* guest_identity =
      FableDirectFindTextureIdentityByObject(guest);
  const FableTextureIdentity* resource_identity =
      FableDirectFindTextureIdentityByObject(resource.guest_address);
  const bool exact_tiny_identity =
      IsFableTinyTitleUploadedTextureIdentity(guest, guest_identity) ||
      IsFableTinyTitleUploadedTextureIdentity(resource.guest_address,
                                             resource_identity) ||
      IsFableTinyTitleUploadedTextureAddress(guest) ||
      IsFableTinyTitleUploadedTextureAddress(resource.guest_address) ||
      IsFableTinyTitleUploadedTextureAddress(resource.parent_address) ||
      IsFableTinyTitleUploadedTextureAddress(base);
  const bool exact_tiny_shape =
      IsFableTinyTitleUploadedTextureIdentityBase(base, width, height);
  if (!exact_tiny_identity && !exact_tiny_shape) {
    return false;
  }
  const bool one_dimensional_upload =
      IsFableOneDimensionalTitleUploadedTextureIdentity(guest, guest_identity) ||
      IsFableOneDimensionalTitleUploadedTextureIdentity(resource.guest_address,
                                                        resource_identity) ||
      IsFableOneDimensionalTitleUploadedTextureIdentityBase(base, width, height);
  if (one_dimensional_upload) {
    return false;
  }

  return !DirectResourceHasMeaningfulTextureUpload(resource) ||
         DirectResourceIsBlankUploadedSampleProxy(resource);
}

bool DirectTinyTitleBlankTextureCanBindLocked(
    const FableDirectRenderCommand& command, uint32_t guest,
    const PlumeTrackedResource* texture) {
  if (!texture || !PlumeGuestImageReady(*texture)) {
    return false;
  }
  if (guest != 0 && texture->guest_address == 0x401314D0u) {
    return false;
  }
  return DirectResourceIsFableTinyTitleNeutralTextureLocked(guest, *texture) &&
         (IsFableTitleSceneTargetLocked(command.resources.render_targets[0]) ||
          IsFableTitleSceneVertexShaderCommandLocked(command) ||
          IsFableFinalTitlePrivateIndirectionCommandLocked(command) ||
          IsFableTitleSceneTextureSyncCommandLocked(command));
}

bool DirectOneDimensionalTinyTitleTextureCanBindLocked(
    uint32_t guest, const PlumeTrackedResource* texture) {
  if (!texture || !IsImageResource(texture->kind) ||
      !PlumeGuestImageReady(*texture) || texture->texture_render_target ||
      texture->texture_depth_target ||
      DirectResourceIsBlankUploadedSampleProxy(*texture)) {
    return false;
  }

  const uint32_t base = PlumeGuestTextureBaseAddress(*texture);
  const uint32_t width = PlumeGuestTextureWidth(*texture);
  const uint32_t height = PlumeGuestTextureHeight(*texture);
  const FableTextureIdentity* guest_identity =
      FableDirectFindTextureIdentityByObject(guest);
  const FableTextureIdentity* texture_identity =
      FableDirectFindTextureIdentityByObject(texture->guest_address);
  return IsFableOneDimensionalTitleUploadedTextureIdentity(guest,
                                                           guest_identity) ||
         IsFableOneDimensionalTitleUploadedTextureIdentity(
             texture->guest_address, texture_identity) ||
         IsFableOneDimensionalTitleUploadedTextureIdentityBase(base, width,
                                                              height);
}

bool DirectTinyTitleCachedTextureCanBindLocked(
    const FableDirectRenderCommand& command, uint32_t guest,
    const PlumeTrackedResource* texture) {
  if (!texture || !IsImageResource(texture->kind) ||
      !PlumeGuestImageReady(*texture) || texture->texture_render_target ||
      texture->texture_depth_target ||
      DirectCommandBindsExactResourceAsTargetLocked(command, *texture) ||
      DirectResourceIsBlankUploadedSampleProxy(*texture) ||
      ((!IsFableTitleSceneTargetLocked(command.resources.render_targets[0]) &&
        !IsFableTitleSceneVertexShaderCommandLocked(command) &&
        !IsFableFinalTitlePrivateIndirectionCommandLocked(command) &&
        !IsFableTitleSceneTextureSyncCommandLocked(command)) &&
       !DirectOneDimensionalTinyTitleTextureCanBindLocked(guest, texture))) {
    return false;
  }

  const uint32_t base = PlumeGuestTextureBaseAddress(*texture);
  const uint32_t width = PlumeGuestTextureWidth(*texture);
  const uint32_t height = PlumeGuestTextureHeight(*texture);
  const FableTextureIdentity* guest_identity =
      FableDirectFindTextureIdentityByObject(guest);
  const FableTextureIdentity* texture_identity =
      FableDirectFindTextureIdentityByObject(texture->guest_address);
  const bool exact_tiny_identity =
      IsFableTinyTitleUploadedTextureIdentity(guest, guest_identity) ||
      IsFableTinyTitleUploadedTextureIdentity(texture->guest_address,
                                             texture_identity) ||
      IsFableTinyTitleUploadedTextureAddress(guest) ||
      IsFableTinyTitleUploadedTextureAddress(texture->guest_address) ||
      IsFableTinyTitleUploadedTextureAddress(texture->parent_address);
  const bool exact_tiny_shape =
      IsFableTinyTitleUploadedTextureIdentityBase(base, width, height);
  if (!exact_tiny_identity && !exact_tiny_shape) {
    return false;
  }

  if (DirectOneDimensionalTinyTitleTextureCanBindLocked(guest, texture)) {
    // Fable's title path binds these 1D helper uploads as ordinary textures.
    // Some contain no nonzero payload in the captured upload, so waiting for a
    // "meaningful" upload turns a valid D3D bind into a stale deferred wait.
    return true;
  }

  return DirectResourceHasMeaningfulTextureUpload(*texture) &&
         !DirectResourceIsBlankUploadedSampleProxy(*texture);
}

bool DirectTinyTitleResourceMatchesFetchInfo(
    const DirectTextureFetchInfo& fetch_info,
    const PlumeTrackedResource* texture) {
  if (!fetch_info.valid || !texture || !IsImageResource(texture->kind) ||
      !PlumeGuestImageReady(*texture)) {
    return false;
  }
  if (PlumeGuestTextureBaseAddress(*texture) != fetch_info.base_address ||
      PlumeGuestTextureWidth(*texture) != fetch_info.width ||
      PlumeGuestTextureHeight(*texture) != fetch_info.height) {
    return false;
  }
  const uint32_t guest_format = PlumeGuestTextureGuestFormat(*texture);
  const uint32_t render_format =
      static_cast<uint32_t>(PlumeGuestTextureFormat(*texture));
  return fetch_info.format == 0u || guest_format == fetch_info.format ||
         render_format == fetch_info.format;
}

PlumeTrackedResource* ResolveDirectTinyTitleUploadedTextureForCommandSlotLocked(
    const FableDirectRenderCommand& command, uint32_t slot,
    const PlumeTrackedResource* skip_texture) {
  if (slot >= command.resources.textures.size()) {
    return nullptr;
  }

  const DirectTextureFetchInfo command_fetch_info =
      DirectTextureFetchInfoFromDwords(
          DirectCommandTextureFetchDwords(command, slot));
  if (!command_fetch_info.valid ||
      !IsFableTinyTitleUploadedTextureIdentityBase(
          command_fetch_info.base_address, command_fetch_info.width,
          command_fetch_info.height)) {
    return nullptr;
  }

  const uint32_t guest = command.resources.textures[slot];
  auto bindable_exact_tiny_upload =
      [&](PlumeTrackedResource* candidate) -> PlumeTrackedResource* {
    return DirectTinyTitleResourceMatchesFetchInfo(command_fetch_info, candidate) &&
                   DirectTinyTitleCachedTextureCanBindLocked(command, guest,
                                                             candidate)
               ? candidate
               : nullptr;
  };

  if (PlumeTrackedResource* sample =
          bindable_exact_tiny_upload(FindDirectResourceLocked(guest))) {
    return sample;
  }
  if (PlumeTrackedResource* sample =
          bindable_exact_tiny_upload(
              skip_texture ? FindDirectResourceLocked(skip_texture->guest_address)
                           : nullptr)) {
    return sample;
  }

  auto bindable_identity = [&](const FableTextureIdentity* identity)
      -> PlumeTrackedResource* {
    if (!IsFableTinyTitleUploadedTextureIdentity(0, identity)) {
      return nullptr;
    }
    const uint32_t identity_addresses[] = {
        identity->object_texture, identity->parent_texture,
        identity->base_address};
    for (uint32_t address : identity_addresses) {
      if (PlumeTrackedResource* sample =
              bindable_exact_tiny_upload(FindDirectResourceLocked(address))) {
        return sample;
      }
    }
    return nullptr;
  };

  if (PlumeTrackedResource* sample =
          bindable_identity(FableDirectFindTextureIdentityByBase(
              command_fetch_info.base_address))) {
    return sample;
  }
  if (PlumeTrackedResource* sample =
          bindable_identity(FableDirectFindTextureIdentityByFetch(
              DirectCommandTextureFetchDwords(command, slot)))) {
    return sample;
  }
  if (const std::vector<uint32_t>* base_objects =
          FableDirectFindTextureIdentityObjectsByBase(
              command_fetch_info.base_address)) {
    for (uint32_t object : *base_objects) {
      if (PlumeTrackedResource* sample = bindable_identity(
              FableDirectFindTextureIdentityByObject(object))) {
        return sample;
      }
    }
  }
  if (const std::vector<uint32_t>* fetch_objects =
          FableDirectFindTextureIdentityObjectsByFetch(
              DirectCommandTextureFetchDwords(command, slot))) {
    for (uint32_t object : *fetch_objects) {
      if (PlumeTrackedResource* sample = bindable_identity(
              FableDirectFindTextureIdentityByObject(object))) {
        return sample;
      }
    }
  }

  const FableTextureHeaderAction* action =
      FableDirectFindTextureHeaderActionForExactFetchIdentity(
          command_fetch_info.base_address, command_fetch_info.width,
          command_fetch_info.height, command_fetch_info.format,
          DirectCommandTextureFetchDwords(command, slot));
  if (action && action->serial != 0 && action->call_serial != 0 &&
      action->context_key != 0 && action->symbol_address != 0 &&
      !action->stack_scratch &&
      DirectTextureFetchDwordsMatch(action->fetch_dwords,
                                    DirectCommandTextureFetchDwords(command,
                                                                    slot)) &&
      action->base_address == command_fetch_info.base_address &&
      action->width == command_fetch_info.width &&
      action->height == command_fetch_info.height &&
      action->format == command_fetch_info.format) {
    const uint32_t action_addresses[] = {
        action->texture_object, action->parent_texture, action->texture_header,
        action->base_address};
    for (uint32_t address : action_addresses) {
      if (PlumeTrackedResource* sample =
              bindable_exact_tiny_upload(FindDirectResourceLocked(address))) {
        return sample;
      }
    }
  }

  if (command_fetch_info.base_address == 0x1A0D7000u &&
      command_fetch_info.width == 16u && command_fetch_info.height == 16u) {
    const uint32_t known_tiny_title_uploads[] = {
        0x404DE490u, 0x404DE4D0u, 0x404DE550u};
    for (uint32_t address : known_tiny_title_uploads) {
      if (PlumeTrackedResource* sample =
              bindable_exact_tiny_upload(FindDirectResourceLocked(address))) {
        return sample;
      }
    }
  }

  return nullptr;
}

PlumeTrackedResource* ResolveDirectNeutralTextureLocked() {
  PlumeTrackedResource* neutral = FindDirectResourceLocked(0x401314D0u);
  return neutral && PlumeGuestImageReady(*neutral) ? neutral : nullptr;
}

bool DirectCommandSlotCanUseNeutralTinyTitleTextureLocked(
    const FableDirectRenderCommand& command, uint32_t slot) {
  if (command.draw.source == RendererDrawEventSource::kPixVideo ||
      slot >= command.resources.textures.size()) {
    return false;
  }
  if (command.resources.textures[slot] != 0) {
    return false;
  }

  const DirectTextureFetchInfo command_fetch_info =
      DirectTextureFetchInfoFromDwords(
          DirectCommandTextureFetchDwords(command, slot));
  if (!command_fetch_info.valid ||
      !IsFableTinyTitleUploadedTextureIdentityBase(
          command_fetch_info.base_address, command_fetch_info.width,
          command_fetch_info.height)) {
    return false;
  }

  return ResolveDirectNeutralTextureLocked() != nullptr;
}

bool IsFablePrivateTextureChainExtent(uint32_t width, uint32_t height) {
  return (width == 256u && height == 256u) ||
         (width == 280u && height == 180u) ||
         (width == 320u && height == 180u) ||
         (width == 480u && height == 270u) ||
         (width == 560u && height == 360u) ||
         (width == 960u && height == 540u);
}

bool IsFablePrivateTextureChainResource(
    const PlumeTrackedResource& resource) {
  if (IsFableTitlePrivateTextureProxyAddress(resource.guest_address) ||
      IsFableTitlePrivateTextureProxyAddress(
          PlumeGuestTextureBaseAddress(resource))) {
    return true;
  }
  if (!IsImageResource(resource.kind) || !PlumeGuestImageReady(resource)) {
    return false;
  }

  const uint32_t width = PlumeGuestTextureWidth(resource);
  const uint32_t height = PlumeGuestTextureHeight(resource);
  if (!IsFablePrivateTextureChainExtent(width, height)) {
    return false;
  }

  if (width == 256u && height == 256u) {
    return DirectResourceIsUnbackedSampleProxy(resource);
  }

  return resource.texture_render_target || resource.texture_depth_target ||
         DirectResourceHasGpuProducedContent(resource) ||
         DirectResourceIsUnbackedSampleProxy(resource) ||
         DirectResourceHasMeaningfulTextureUpload(resource);
}

bool ShouldRetainFablePrivateTitleCopyGraphForDestroyedResourceLocked(
    uint32_t address, const PlumeTrackedResource* resource) {
  auto is_private_title_header = [&](uint32_t candidate) {
    return IsFableTitlePrivateTextureProxyAddress(candidate) ||
           IsFableMutablePrivateTextureHeaderAddress(candidate);
  };
  auto has_exact_destination_identity = [&](uint32_t candidate) {
    return candidate != 0 &&
           (FableDirectFindSurfaceTextureLinkForDestinationTexture(candidate) ||
            FableDirectFindPrivateTextureCopyActionForDestinationTexture(
                candidate));
  };

  bool private_title_header = is_private_title_header(address);
  if (resource) {
    private_title_header =
        private_title_header ||
        is_private_title_header(resource->guest_address) ||
        is_private_title_header(resource->parent_address) ||
        is_private_title_header(PlumeGuestTextureBaseAddress(*resource));
    if (resource->kind != FableGuestResourceKind::kTexture ||
        resource->texture_render_target || resource->texture_depth_target) {
      return false;
    }
  }
  if (!private_title_header) {
    return false;
  }

  if (has_exact_destination_identity(address)) {
    return true;
  }
  if (!resource) {
    return false;
  }
  return has_exact_destination_identity(resource->guest_address) ||
         has_exact_destination_identity(resource->parent_address) ||
         has_exact_destination_identity(PlumeGuestTextureBaseAddress(*resource));
}

const char* DirectPrivateTextureCopyActionMatchName(
    DirectPrivateTextureCopyActionMatch match) {
  switch (match) {
    case DirectPrivateTextureCopyActionMatch::kNone:
      return "none";
    case DirectPrivateTextureCopyActionMatch::kExactDestination:
      return "exact-destination";
    case DirectPrivateTextureCopyActionMatch::kExactTrackedDestination:
      return "exact-tracked-destination";
    case DirectPrivateTextureCopyActionMatch::kExactParentDestination:
      return "exact-parent-destination";
    case DirectPrivateTextureCopyActionMatch::kExactIdentityDestination:
      return "exact-identity-destination";
    case DirectPrivateTextureCopyActionMatch::kExactSurfaceTextureLink:
      return "exact-surface-link";
    case DirectPrivateTextureCopyActionMatch::kExactCurrentColorAction:
      return "exact-current-color-action";
  }
  return "unknown";
}

void CountDirectPrivateTextureCopyActionMatchLocked(
    DirectPrivateTextureCopyActionMatch match) {
  switch (match) {
    case DirectPrivateTextureCopyActionMatch::kExactDestination:
    case DirectPrivateTextureCopyActionMatch::kExactTrackedDestination:
    case DirectPrivateTextureCopyActionMatch::kExactParentDestination:
    case DirectPrivateTextureCopyActionMatch::kExactIdentityDestination:
    case DirectPrivateTextureCopyActionMatch::kExactSurfaceTextureLink:
    case DirectPrivateTextureCopyActionMatch::kExactCurrentColorAction:
      ++g_direct_renderer.frame_private_copy_exact_matches;
      break;
    case DirectPrivateTextureCopyActionMatch::kNone:
      break;
  }
}

bool NearlyEqualPrivateTextureActionFloat(float lhs, float rhs, float epsilon) {
  return std::fabs(lhs - rhs) <= epsilon;
}

bool DirectPrivateTextureCopyActionHasExactWrapperIdentity(
    const FablePrivateTextureCopyAction& action) {
  return action.wrapper_call_serial != 0 || action.wrapper_context_key != 0 ||
         action.wrapper_symbol_address != 0;
}

